# Author: Alexis Mousset <contact@amousset.me>
# Adapted from https://protesilaos.com/emacs/modus-themes, by Protesilaos Stavrou
# Version 4.6.0
#

# Syntax highlighting
# -------------------
"type" = "cyan-cooler"
"constructor" = "cyan-cooler"

"constant" = "blue-cooler"
"constant.character.escape" = "magenta"

"string" = "blue-warmer"
"string.regexp" = "magenta-faint"
"string.special" = "blue-faint" # used for colors in CSS

"comment" = "fg-dim"

"variable.parameter" = "cyan"
"variable.builtin" = "magenta-warmer"
"label" = "fg-dim" # used for language in markdown code blocks
"keyword" = "magenta-cooler"
"keyword.directive" = "red-cooler"
"function" = "magenta"
"function.macro" = "red-cooler"

punctuation = "fg-dim"
"tag" = "magenta-cooler"
"attribute" = "cyan"
"namespace" = "cyan"
"special" = "red-cooler"

"markup.heading.marker" = "fg-dim"
"markup.heading.1" = { fg = "fg-main", modifiers = ["bold"] }
"markup.heading.2" = { fg = "yellow-faint", modifiers = ["bold"] }
"markup.heading.3" = { fg = "fg-alt", modifiers = ["bold"] }
"markup.heading.4" = { fg = "magenta", modifiers = ["bold"] }
"markup.heading.5" = { fg = "green-faint", modifiers = ["bold"] }
"markup.heading.6" = { fg = "red-faint", modifiers = ["bold"] }
"markup.list" = "fg-dim"
"markup.list.checked" = { fg = "yellow-warmer" }
"markup.list.unchecked" = { fg = "yellow-warmer" }
"markup.bold" = { modifiers = ["bold"] }
"markup.italic" = { modifiers = ["italic"] }
"markup.strikethrough" = { modifiers = ["crossed_out"] }
"markup.link.url" = { fg = "cyan" }
"markup.link.text" = { fg = "blue-warmer", modifiers = ["underlined"] }
"markup.raw.block" = { bg = "bg-dim" }
"markup.raw.inline" = { fg = "green-cooler" }

"diff.plus" = { fg = "fg-added", bg = "bg-added" }
"diff.plus.gutter" = "green-intense"
"diff.minus" = { fg = "fg-removed", bg = "bg-removed" }
"diff.minus.gutter" = "red-intense"
"diff.delta" = { fg = "fg-changed", bg = "bg-changed" }
"diff.delta.gutter" = "yellow-intense"

# User Interface
# --------------

"ui.background" = { bg = "bg-main" }
"ui.background.separator" = { fg = "fg-dim" }

"ui.linenr" = { fg = "fg-dim", bg = "bg-dim" }
"ui.linenr.selected" = { fg = "fg-main", bg = "bg-active" }

"ui.statusline" = { fg = "fg-mode-line-active", bg = "bg-mode-line-active" }
"ui.statusline.inactive" = { fg = "fg-mode-line-inactive", bg = "bg-mode-line-inactive" }
"ui.statusline.normal" = { fg = "blue-warmer" }
"ui.statusline.insert" = { fg = "green-warmer" }
"ui.statusline.select" = { fg = "magenta-warmer" }
"ui.statusline.separator" = { fg = "border-mode-line-active" }

"ui.bufferline" = { bg = "bg-tab-bar" }
"ui.bufferline.active" = { bg = "bg-tab-current", fg = "fg-mode-line-active" }
"ui.bufferline.background" = { bg = "bg-tab-bar" }

"ui.popup" = { fg = "fg-main", bg = "bg-dim" }
"ui.popup.info" = { fg = "fg-main", bg = "bg-active" }
"ui.picker.header" = { fg = "fg-main", bg = "bg-active", modifiers = ["bold"] }
"ui.picker.header.column" = { fg = "fg-dim", bg = "bg-active" }
"ui.picker.header.column.active" = { fg = "fg-main", bg = "bg-active", modifiers = ["bold"] }
"ui.window" = { fg = "fg-dim" }
"ui.help" = { fg = "fg-main", bg = "bg-active" }
"ui.gutter" = { bg = "bg-dim" }
"ui.debug.breakpoint" = { fg = "red-intense" }
"ui.debug.active" = { fg = "yellow-intense" }
"ui.debug" = { fg = "yellow-intense" }
"ui.gutter.selected" = { bg = "bg-active" }
"ui.text" = "fg-main"
"ui.text.directory" = "blue"
"ui.text.focus" = { fg = "fg-main", bg = "bg-completion", modifiers = ["bold"] }
"ui.text.inactive" = { fg = "fg-dim" }
"ui.text.info" = { fg = "blue-warmer" }
"ui.virtual" = "bg-active"
"ui.virtual.ruler" = { bg = "bg-dim" }
"ui.virtual.inlay-hint" = { fg = "fg-dim", modifiers = ["italic"] }
"ui.virtual.inlay-hint.parameter" = { fg = "fg-dim", modifiers = ["italic"] }
"ui.virtual.inlay-hint.type" = { fg = "fg-dim", modifiers = ["italic"] }
"ui.virtual.indent-guide" = { fg = "fg-dim" }
"ui.virtual.whitespace" = { fg = "fg-dim" }
"ui.virtual.wrap" = { fg = "fg-dim" }
"ui.virtual.jump-label" = { fg = "yellow-cooler", modifiers = ["bold"] }

"ui.selection" = { bg = "bg-inactive" }
"ui.selection.primary" = { bg = "bg-active" }

"ui.cursor" = { fg = "bg-main", bg = "fg-main" }
"ui.cursor.normal" = { fg = "bg-main", bg = "fg-main" }
"ui.cursor.insert" = { fg = "bg-main", bg = "fg-main" }
"ui.cursor.select" = { fg = "bg-main", bg = "fg-main" }
"ui.cursor.primary" = { fg = "bg-main", bg = "fg-dim" }
"ui.cursor.primary.normal" = { fg = "bg-main", bg = "fg-dim" }
"ui.cursor.primary.insert" = { fg = "bg-main", bg = "fg-dim" }
"ui.cursor.primary.select" = { fg = "bg-main", bg = "fg-dim" }
"ui.cursor.match" = { fg = "fg-main", bg = "bg-paren-match" }
"ui.cursorline.primary" = { bg = "bg-hl-line" }

"ui.highlight" = { bg = "bg-hl-line" }
"ui.highlight.frameline" = { bg = "bg-paren-match" }

"ui.menu" = { fg = "fg-main", bg = "bg-dim" }
"ui.menu.selected" = { fg = "fg-main", bg = "bg-completion", modifiers = ["bold"] }
"ui.menu.scroll" = { fg = "fg-dim", bg = "bg-cyan-intense" }

"diagnostic.error" = { underline = { color = "red-intense", style = "curl" } }
"diagnostic.warning" = { underline = { color = "yellow-intense", style = "curl" } }
"diagnostic.info" = { underline = { color = "cyan-intense", style = "curl" } }
"diagnostic.hint" = { underline = { color = "blue-intense", style = "curl" } }
"diagnostic.unnecessary" = { modifiers = ["dim"] }
"diagnostic.deprecated" = { modifiers = ["crossed_out"] }

error = "red"
warning = "yellow-warmer"
info = "cyan-cooler"
hint = "blue-cooler"

[palette]
# Basic values
bg-main = "#ffffff"
bg-dim = "#f2f2f2"
fg-main = "#000000"
fg-dim = "#595959"
fg-alt = "#193668"
bg-active = "#c4c4c4"
bg-inactive = "#e0e0e0"

# Common accent foregrounds
red = "#a60000"
red-warmer = "#972500"
red-cooler = "#a0132f"
red-faint = "#7f0000"
red-intense = "#d00000"
green = "#006800"
green-warmer = "#316500"
green-cooler = "#00663f"
green-faint = "#2a5045"
green-intense = "#008900"
yellow = "#6f5500"
yellow-warmer = "#884900"
yellow-cooler = "#7a4f2f"
yellow-faint = "#624416"
yellow-intense = "#808000"
blue = "#0031a9"
blue-warmer = "#3548cf"
blue-cooler = "#0000b0"
blue-faint = "#003497"
blue-intense = "#0000ff"
magenta = "#721045"
magenta-warmer = "#8f0075"
magenta-cooler = "#531ab6"
magenta-faint = "#7c318f"
magenta-intense = "#dd22dd"
cyan = "#005e8b"
cyan-warmer = "#3f578f"
cyan-cooler = "#005f5f"
cyan-faint = "#005077"
cyan-intense = "#008899"

# Common accent backgrounds
bg-red-intense = "#ff8f88"
bg-green-intense = "#8adf80"
bg-yellow-intense = "#f3d000"
bg-blue-intense = "#bfc9ff"
bg-magenta-intense = "#dfa0f0"
bg-cyan-intense = "#a4d5f9"

bg-red-subtle = "#ffcfbf"
bg-green-subtle = "#b3fabf"
bg-yellow-subtle = "#fff576"
bg-blue-subtle = "#ccdfff"
bg-magenta-subtle = "#ffddff"
bg-cyan-subtle = "#bfefff"

bg-red-nuanced = "#ffe8e8"
bg-green-nuanced = "#e0f6e0"
bg-yellow-nuanced = "#f8f0d0"
bg-blue-nuanced = "#ecedff"
bg-magenta-nuanced = "#f8e6f5"
bg-cyan-nuanced = "#e0f2fa"

# Special purpose
bg-completion = "#c0deff"
bg-hl-line = "#dae5ec"

bg-mode-line-active = "#c8c8c8"
fg-mode-line-active = "#000000"
border-mode-line-active = "#5a5a5a"
bg-mode-line-inactive = "#e6e6e6"
fg-mode-line-inactive = "#585858"

modeline-err = "#7f0000"
modeline-warning = "#5f0070"
modeline-info = "#002580"

bg-tab-bar = "#dfdfdf"
bg-tab-current = "#ffffff"
bg-tab-other = "#c2c2c2"

# Diffs
bg-added = "#c1f2d1"
fg-added = "#005000"
bg-changed = "#ffdfa9"
fg-changed = "#553d00"
bg-removed = "#ffd8d5"
fg-removed = "#8f1313"

# Paren match
bg-paren-match = "#5fcfff"
